<template><dl class="confirmation-details"><template v-for="line in lines" :key="line.label + line.value"><dt>{{ line.label }}</dt><dd>{{ line.value }}</dd></template></dl></template>
<script setup lang="ts">
const props = defineProps<{ value: unknown }>();
const labels: Record<string, string> = { name: '名称', unitName: '比赛项目', unit_name: '比赛项目', event_name: '赛事', location: '场地', type_name: '比赛类型', entryType: '参赛形式', teamName: '代表队伍', status: '当前状态', publicationStatus: '发布状态', holdingStatus: '举办状态', registrationOpensAt: '报名开始', registrationClosesAt: '报名截止', startsAt: '比赛开始', endsAt: '比赛结束', declarationText: '参赛声明', rulesText: '规程', noticeText: '须知', feeAmount: '本单费用（元）', feeDescription: '收费说明', obligationStatus: '资金状态', payInstruction: '付款指引', contactName: '联系人', contactMethod: '联系方式', nickname: '队员昵称', legalName: '参赛人', title: '称号或奖项', ready: '本人准备', announcement: '房间公告', message: '办理说明', reason: '依据', missingResults: '待确认场次', openObligations: '待处理付款义务', pendingFundActions: '资金后续待办', openIssues: '未处理问题', readyForPublicationReview: '发布条件已核对', nextStep: '下一步', maxMembers: '名单人数上限', max_members: '房间人数上限' };
const values: Record<string, string> = { individual: '单打', pair: '双打', team: '团体', draft: '草稿', published: '已发布', normal: '正常举办', forming: '正在集结', ready: '已准备', submitted: '已提交', approved: '已通过', pending_confirmation: '等待本人确认', confirmed: '已确认', open: '待处理', settled: '已足额登记', not_required: '无需付款', certified: '具备办赛资格', restricted: '办赛资格暂停' };
const lines = computed(() => { const out: { label: string; value: string }[] = []; function walk(v: unknown) { if (Array.isArray(v)) { v.forEach(walk); return; } if (v && typeof v === 'object') { Object.entries(v).forEach(([key, item]) => { if (item === null || item === undefined) return; if (typeof item === 'object') walk(item); else if (labels[key]) out.push({ label: labels[key], value: typeof item === 'boolean' ? item ? '是' : '否' : values[String(item)] || String(item) }); }); } } walk(props.value); return out; });
</script>
